def _drop_index_if_present(index_name: str, table_name: str) -> None:
    """Drop an index by name, wherever the table now lives.

    Migration 021 moves the tables the models declare into their schemas, so
    an index created unqualified can end up in a schema. The downgrade has to
    find it wherever it is - and must not fail when it is not there at all.
    """
    import sqlalchemy as sa

    bind = op.get_bind()
    schemas = [
        row[0]
        for row in bind.execute(
            sa.text(
                "SELECT table_schema FROM information_schema.tables "
                "WHERE table_name = :table AND table_type = 'BASE TABLE'"
            ),
            {"table": table_name},
        ).all()
    ]
    for schema in schemas or [None]:
        if schema:
            bind.execute(
                sa.text(f'DROP INDEX IF EXISTS "{schema}"."{index_name}"')
            )
        else:
            bind.execute(sa.text(f'DROP INDEX IF EXISTS "{index_name}"'))


